package net.officefloor.hq.app.person;

import net.officefloor.hq.app.rollup.Actor;
import net.officefloor.hq.app.sheet.InvalidSheetRequestException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

public class ValidateMerge {
    public void validate(@RequestBody MergeRequest request, Out<MergeRequest> body, Out<Actor> actor)
            throws InvalidSheetRequestException {
        if (request == null || request.intoId() == null) {
            throw new InvalidSheetRequestException("Choose the person to merge into");
        }
        body.set(request);
        actor.set(new Actor(request.user()));
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.settings.Role;
import net.officefloor.hq.app.settings.Settings;
import net.officefloor.hq.app.sheet.InvalidSheetRequestException;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;

/** A steward merges the person into another on the sheet (see {@link People#merge}). Both are read
 *  afresh and locked. Refused: anyone but a steward, the person themselves, and either of them
 *  retired. Publishes the person merged into, as they are now. */
public class MergePerson {
    public void merge(@PathVariable("sheetId") String sheetId, @PathVariable("personId") long personId,
            @Val MergeRequest request, People people, Settings settings, Out<Person> personOut,
            Out<Merger> mergerOut) throws PersonNotFoundException, InvalidSheetRequestException {
        if (settings.role(sheetId, request.user()) != Role.STEWARD) {
            throw new InvalidSheetRequestException("Only a steward can merge people");
        }
        if (request.intoId() == personId) {
            throw new InvalidSheetRequestException("A person cannot be merged into themselves");
        }
        Person from = people.lock(sheetId, personId);
        if (from == null) throw new PersonNotFoundException(personId);
        Person into = people.lock(sheetId, request.intoId());
        if (into == null) throw new InvalidSheetRequestException("No such person on this sheet");
        if (from.isRetired() || into.isRetired()) {
            throw new InvalidSheetRequestException("A retired person cannot be merged, nor merged into");
        }
        people.merge(from, into);
        Person now = people.find(sheetId, into.getId());
        personOut.set(now);
        mergerOut.set(new Merger(from, now, request.user()));
    }
}
package net.officefloor.hq.app.person;

/** A person just merged into another, and by whom. */
public record Merger(Person from, Person into, String user) {
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.Audit;
import net.officefloor.plugin.variable.Val;

/** Runs after the merge is saved, so a refused one writes no audit line. */
public class RecordPersonMerged {
    public void record(@Val Merger merger, Audit audit) {
        audit.record("PERSON_MERGED sheet=" + merger.into().getSheetId() + " by=" + merger.user()
                + " from=" + merger.from().getName() + " into=" + merger.into().getName());
    }
}
package net.officefloor.hq.app.rollup;

/** Who makes a change, published by the change's validating step for the steps after it. */
public record Actor(String user) {
}
package net.officefloor.hq.app.rollup;

import net.officefloor.plugin.variable.Val;

/** Runs after the change's own audit lines: audits the figures it moved. */
public class RecordRollup {
    public void record(@Val RollupBefore before, @Val Actor actor, Rollup rollup) {
        rollup.record(before.sheetId(), before.snapshot(), actor.user());
    }
}
package net.officefloor.hq.app.rollup;

import java.time.LocalDate;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.sheet.Sheets;
import net.officefloor.plugin.variable.Val;

/** Runs before a new today takes effect: when the today moves, one SNAPSHOT line per person, in list
 *  order, with their due-total as it stood on the day being left (n/a when it is n/a). */
public class RecordSnapshot {
    public void record(@Val RollupBefore before, @Val LocalDate today, @Val Actor actor, Sheets sheets, Audit audit) {
        if (today.equals(sheets.today(before.sheetId()))) return;
        String prefix = " sheet=" + before.sheetId() + " by=" + actor.user();
        before.snapshot().people().values().forEach(was -> audit.record("SNAPSHOT" + prefix + " name=" + was.name()
                + " due-total=" + (was.dueTotal() == null ? "n/a" : was.dueTotal().setScale(2).toPlainString())));
    }
}
package net.officefloor.hq.app.rollup;

/** The sheet's figures as they were before the change. */
public record RollupBefore(String sheetId, Snapshot snapshot) {
}
package net.officefloor.hq.app.rollup;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.Claims;
import net.officefloor.hq.app.claim.Figures;
import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.rate.Rates;
import net.officefloor.hq.app.settings.Settings;
import net.officefloor.hq.app.sheet.Sheets;
import org.springframework.stereotype.Service;

/**
 * The figures the screen shows — each person's claimed and due-total, the sheet's claimed-total and
 * due-total, and each one's overdue-total and the sheet's — worked out as the screen does, so a change can audit the ones it moved: one ROLLUP
 * line per person whose figures changed (a new person counts as changed), then a TOTALS line when
 * the sheet's totals changed.
 */
@Service
public class Rollup {

    private static final BigDecimal ZERO = BigDecimal.ZERO.setScale(2);

    private final People people;
    private final Claims claims;
    private final Figures figures;
    private final Rates rates;
    private final Sheets sheets;
    private final Audit audit;
    private final Settings settings;

    public Rollup(People people, Claims claims, Figures figures, Rates rates, Sheets sheets, Audit audit, Settings settings) {
        this.people = people;
        this.claims = claims;
        this.figures = figures;
        this.rates = rates;
        this.sheets = sheets;
        this.audit = audit;
        this.settings = settings;
    }

    /** The sheet's figures now. A person's due-total is the sum of their counting claims' figures (a
     *  person's OPEN claims dated within a hold of theirs, or any once today reaches their retirement
     *  date, do not count, unless a statement binds them),
     *  n/a when there is no rate today and none has a figure, at most the sheet's cap (n/a is not
     *  capped); the sheet's skips the n/a ones, and its due and overdue totals leave out the single
     *  highest and lowest person's figure when three or more have one. */
    public Snapshot snapshot(String sheetId) {
        LocalDate today = sheets.today(sheetId);
        List<Claim> all = claims.onSheet(sheetId);
        Map<Long, Snapshot.PersonFigures> figuresOf = new LinkedHashMap<>();
        BigDecimal claimedTotal = ZERO;
        List<BigDecimal> dues = new ArrayList<>();
        List<BigDecimal> overdues = new ArrayList<>();
        for (Person person : people.onSheet(sheetId)) {
            BigDecimal claimed = ZERO;
            BigDecimal due = ZERO;
            BigDecimal overdue = ZERO;
            boolean any = false;
            for (Claim claim : all) {
                if (claim.getPersonId() != person.getId() || !person.counts(claim)) continue;
                claimed = claimed.add(claim.getAmount());
                String grade = person.gradeOn(claim.getDate());
                BigDecimal figure = figures.due(claim, grade);
                if (figure != null) {
                    due = due.add(figure);
                    any = true;
                    if (figures.overdue(claim, grade)) {
                        overdue = overdue.add(figure);
                    }
                }
            }
            if (!any && rates.pct(sheetId, person.gradeOn(today), today) == null) due = null;
            due = settings.capped(sheetId, due);
            figuresOf.put(person.getId(), new Snapshot.PersonFigures(person.getName(), claimed, due, overdue));
            claimedTotal = claimedTotal.add(claimed);
            if (due != null) dues.add(due);
            overdues.add(overdue);
        }
        return new Snapshot(figuresOf, claimedTotal, trimmed(dues), trimmed(overdues));
    }

    /** The figures added up, leaving out the single highest and lowest when there are three or more. */
    private static BigDecimal trimmed(List<BigDecimal> figures) {
        List<BigDecimal> sorted = new ArrayList<>(figures);
        sorted.sort(BigDecimal::compareTo);
        if (sorted.size() >= 3) sorted = sorted.subList(1, sorted.size() - 1);
        return sorted.stream().reduce(ZERO, BigDecimal::add);
    }

    /** Audit the figures that moved between `before` and the sheet now. */
    public void record(String sheetId, Snapshot before, String user) {
        Snapshot after = snapshot(sheetId);
        String prefix = " sheet=" + sheetId + " by=" + user;
        after.people().forEach((id, now) -> {
            Snapshot.PersonFigures was = before.people().get(id);
            if (was != null && same(was.claimed(), now.claimed()) && same(was.dueTotal(), now.dueTotal())
                    && same(was.overdueTotal(), now.overdueTotal())) return;
            audit.record("ROLLUP" + prefix + " person=" + now.name() + " claimed=" + show(now.claimed())
                    + " due-total=" + show(now.dueTotal()) + " overdue-total=" + show(now.overdueTotal()));
        });
        if (!same(before.claimedTotal(), after.claimedTotal()) || !same(before.dueTotal(), after.dueTotal())
                || !same(before.overdueTotal(), after.overdueTotal())) {
            audit.record("TOTALS" + prefix + " claimed-total=" + show(after.claimedTotal())
                    + " due-total=" + show(after.dueTotal()) + " overdue-total=" + show(after.overdueTotal()));
        }
    }

    private static boolean same(BigDecimal a, BigDecimal b) {
        return a == null || b == null ? Objects.equals(a, b) : a.compareTo(b) == 0;
    }

    private static String show(BigDecimal value) {
        return value == null ? "n/a" : value.setScale(2).toPlainString();
    }
}
package net.officefloor.hq.app.rollup;

import java.math.BigDecimal;
import java.util.Map;

/** Every person's figures on a sheet at one moment, keyed by person id in the order they were
 *  added, and the sheet's totals. A due-total is null when it is n/a. An overdue-total is the dues of
 *  the counting OPEN (or PENDING) claims whose due-by is before the sheet's today (n/a ones skipped). */
public record Snapshot(Map<Long, PersonFigures> people, BigDecimal claimedTotal, BigDecimal dueTotal, BigDecimal overdueTotal) {

    public record PersonFigures(String name, BigDecimal claimed, BigDecimal dueTotal, BigDecimal overdueTotal) {
    }
}
package net.officefloor.hq.app.rollup;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;

/** Runs before the change: keeps the sheet's figures as they were. */
public class SnapshotRollup {
    public void snapshot(@PathVariable("sheetId") String sheetId, Rollup rollup, Out<RollupBefore> before) {
        before.set(new RollupBefore(sheetId, rollup.snapshot(sheetId)));
    }
}

