import { asString, useSearchParam } from '../../url/useSearchParam';

/**
 * The date this user's screen shows the sheet as of (yyyy-mm-dd), or '' for the sheet as it stands.
 * It lives in the URL (`asof`), so it is this screen's alone. While it is set every read is of the
 * sheet as it stood at the end of that date, and every change is refused (see api/http.ts).
 */
export function useAsOf() {
  return useSearchParam('asof', asString);
}

/** A read's query key: the live key, or one apart from it for the sheet as of a date. It keeps the
 *  live key as its prefix, so invalidating the live key re-reads both. */
export function asOfKey<K extends readonly unknown[]>(key: K, asOf: string): K {
  return (asOf === '' ? key : [...key, { asOf }]) as unknown as K;
}

/** A read's path, asking for the sheet as of the date when one is set. */
export function asOfPath(path: string, asOf: string): string {
  return asOf === '' ? path : `${path}${path.includes('?') ? '&' : '?'}asOf=${encodeURIComponent(asOf)}`;
}
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { asOfKey, asOfPath, useAsOf } from '../asof/useAsOf';

/** `version` counts the person's saves; an edit sends the version it loaded, so a save made by
 *  someone else in the meantime refuses it. `statementCount` is how many statements have been
 *  taken for them; `statedTotal` the last one's due-total (two decimals, null when it was n/a or
 *  none was taken) and `statementDate` its date (yyyy-mm-dd, null when none was taken).
 *  `retired` is whether a retirement date is set (whatever the date), `retiredFrom` that date
 *  (yyyy-mm-dd, null when not retired). `held` is whether they have any hold; `holds` every hold, in the
 *  order added, from a date to a date (both inclusive; `to` null: open-ended). Their OPEN claims
 *  dated within a hold count in no live total, nor any OPEN or PENDING claim of theirs once the sheet's today
 *  reaches their retirement date, unless a statement binds them. `patrons` are the ids of the people they have named as patrons, in
 *  the order they were named. `grade` is the grade in force on the sheet's today when they were read;
 *  `grades` every grade recorded, by from-date (null: from the beginning of time, first). `terms` are
 *  the person's own terms in days (null: none), ahead of their grade's and the sheet's.
 *  `contact` is the person's contact, trimmed and lower-cased (null: none). `aliases` are the
 *  person's aliases, sorted as names are compared; the quick-add bar and the paste box find a
 *  person by an alias as well as by the name. */
export type Person = {
  id: number;
  name: string;
  grade: string;
  grades: { grade: string; from: string | null }[];
  version: number;
  statementCount: number;
  statedTotal: string | null;
  statementDate: string | null;
  retired: boolean;
  retiredFrom: string | null;
  held: boolean;
  holds: { from: string; to: string | null }[];
  patrons: number[];
  terms: number | null;
  contact: string | null;
  aliases: string[];
};

/** Whether the sheet's `today` (yyyy-mm-dd) has reached the person's retirement date. */
export function retiredOut(person: Person, today: string): boolean {
  return person.retiredFrom !== null && today !== '' && today >= person.retiredFrom;
}

/** Whether a claim of the person's dated `date` (yyyy-mm-dd) is held out of the live totals: the date
 *  falls within any of the person's holds, or the sheet's `today` has reached their retirement date. */
export function heldOn(person: Person, date: string, today: string): boolean {
  return retiredOut(person, today) || person.holds.some((h) => date >= h.from && (h.to === null || date <= h.to));
}

/** By person id, whether a claim dated then is held out (see `heldOn`) on the sheet's `today`. */
export function heldOnBy(people: Person[], today: string): (personId: number, date: string) => boolean {
  const byId = new Map(people.map((p) => [p.id, p]));
  return (personId, date) => {
    const p = byId.get(personId);
    return p !== undefined && heldOn(p, date, today);
  };
}

export const GRADES = ['A', 'B', 'C'] as const;
import { gradeOn, heldOnBy, usePeople } from '../people/usePeople';
import { rateOn, totalDue, trimmedTotal, useRates } from '../rates/useRates';
import { useCap, useFloor, useLate } from '../settings/useSettings';
import { useSheetToday } from '../sheet/useSheet';
import { claimed, isOpen, live, overdueFigures, personDueCents, useClaims } from './useClaims';

/**
 * The sheet's totals: its claimed-total, everyone's counted (OPEN or SETTLED) claims added up
 * (not OPEN ones dated within their person's hold, unless stated), and its due-total, everyone's due-total
 * added up (a person whose due-total is n/a is skipped), and how many of the claims that count are
 * overdue, with their dues added up. Both due and overdue totals leave out the single highest and
 * lowest person's figure when three or more people have one. Its settled-total and open-total are
 * everyone's due-total before the cap split into SETTLED and OPEN-or-PENDING claims, simply added up. One place, so every screen repeating a total shows the same figure.
 */
export function useSheetTotals(sheet: string) {
  const { data: all = [] } = useClaims(sheet);
  const { data: people = [] } = usePeople(sheet);
  const { data: rates = [] } = useRates(sheet);
  const today = useSheetToday(sheet);
  const claims = live(all, heldOnBy(people, today));
  const floor = useFloor(sheet);
  const late = useLate(sheet);
  const cap = useCap(sheet);
  const dues = people.map((p) =>
    personDueCents(claims.filter((c) => c.personId === p.id), floor, rateOn(rates, gradeOn(p, today), today), (d) => rateOn(rates, gradeOn(p, d), d), late, cap),
  );
  // Everyone's due-total before the cap, split into its SETTLED and its OPEN-and-PENDING part.
  const part = (keep: (c: (typeof claims)[number]) => boolean) =>
    people.map((p) =>
      personDueCents(claims.filter((c) => c.personId === p.id && keep(c)), floor, rateOn(rates, gradeOn(p, today), today), (d) => rateOn(rates, gradeOn(p, d), d), late),
    );
  const over = people.map((p) =>
    overdueFigures(claims.filter((c) => c.personId === p.id), late, floor, (d) => rateOn(rates, gradeOn(p, d), d)),
  );
  return {
    claimedTotal: claimed(claims),
    dueTotal: trimmedTotal(dues),
    settledTotal: totalDue(part((c) => c.status === 'SETTLED')),
    openTotal: totalDue(part(isOpen)),
    overdueCount: over.reduce((n, o) => n + o.count, 0),
    overdueTotal: trimmedTotal(over.map((o) => o.cents)),
  };
}

